// spec: specs/auth-security.md §10 · кейсы auth-21 … auth-24 (.qa/tests/auth-security/)
// #3c03f6 (בקשת לקוח, 17.11; документация не обновлена): новый מפיץ регистрируется и получает отдельный пустой склад;
//   склады полностью изолированы. Регистрация (отправка /register) — только вручную (создание аккаунта), здесь форма НЕ отправляется.
// Второй מפיץ — dist2 (.qa/auth/dist2.json, бизнес «test»). Его данные — только архивные QA-AUTO-6aae65-C / -P (в UI не видны, смотреть через API).
// Не дублирует: distributor-isolation-api.spec (RPC create_*_order, customer_prices), orders-no-direct-insert-api.spec, orders/order-by-number-url.spec.
import { test, expect } from '../../fixtures';
import { openApp, sb } from './_supabase';

const DIST2_CUSTOMER = 'cb15460a-a222-42bf-97d8-462b752a89ac'; // QA-AUTO-6aae65-C (архивный, свой у dist2)
const DIST2_PRODUCT = 'e51273eb-7704-407d-b7aa-54544afd3033'; // QA-AUTO-6aae65-P (архивный, свой у dist2)

test.describe('auth-security — רישום מפיץ חדש ובידוד מחסנים בין מפיצים (#3c03f6)', () => {
  test('אורח: ב-/login קישור «מפיץ חדש? פתיחת עסק ומחסן משלך» → /register עם שדות הרשמה (בלי שליחה); שם הפלטפורמה «קטלוג והזמנות» #3c03f6 @desktop @prod-safe', async ({ asUser }) => {
    const guest = await asUser('guest');
    await guest.goto('/login');
    await expect(guest.getByRole('heading', { level: 1, name: 'התחברות' })).toBeVisible({ timeout: 30_000 });
    await expect(guest, 'название платформы во вкладке').toHaveTitle('קטלוג והזמנות');
    await expect(guest.getByText('קטלוג והזמנות', { exact: true }).first()).toBeVisible();
    await guest.getByRole('link', { name: 'מפיץ חדש? פתיחת עסק ומחסן משלך' }).click();
    await expect(guest).toHaveURL(/\/register$/);
    await expect(guest.getByRole('heading', { level: 1, name: 'הרשמת מפיץ חדש' })).toBeVisible({ timeout: 15_000 });
    await expect(guest.getByText('פתיחת עסק ומחסן חדשים, ריקים, שרק אתה והצוות שלך רואים')).toBeVisible();
    for (const name of [/^שם העסק/, /^שם מלא/, /^טלפון/, /^אימייל/, /^סיסמה/]) {
      await expect(guest.getByRole('textbox', { name }).first(), `поле ${name}`).toBeVisible();
    }
    await expect(guest, 'название платформы во вкладке регистрации').toHaveTitle('קטלוג והזמנות');
    // форма не отправляется: регистрация — только вручную (создание аккаунта)
  });

  test('dist2 (מפיץ שני): קטלוג, לקוחות והזמנות ריקים — אין נתונים של «באנגו דלי» (מוצרים, לקוח «test», הזמנות) #3c03f6 @desktop @prod-safe', async ({ asUser }) => {
    const admin = await asUser('admin');
    await openApp(admin);
    const prods = await sb(admin, 'GET', 'products?select=name&order=created_at.desc&limit=3');
    expect(prods.status, 'admin видит свои товары').toBe(200);
    const adminNames: string[] = prods.body.map((p: any) => p.name).filter(Boolean);
    expect(adminNames.length, 'у admin есть товары (маркеры)').toBeGreaterThan(0);

    const dist2 = await asUser('dist2');
    await dist2.goto('/catalog');
    await expect(dist2.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 30_000 });
    await expect(dist2.getByText('עדיין אין מוצרים בקטלוג')).toBeVisible({ timeout: 30_000 });
    for (const n of adminNames) await expect(dist2.getByText(n, { exact: false }), `товар admin «${n}» не виден`).toHaveCount(0);

    await dist2.goto('/customers');
    await expect(dist2.getByRole('heading', { level: 1, name: 'לקוחות' })).toBeVisible({ timeout: 30_000 });
    await expect(dist2.getByText('עדיין אין לקוחות עסקיים')).toBeVisible({ timeout: 30_000 });

    await dist2.goto('/orders');
    await expect(dist2.getByRole('heading', { level: 1, name: 'הזמנות' })).toBeVisible({ timeout: 30_000 });
    await expect(dist2.getByText('אין הזמנות נכנסות')).toBeVisible({ timeout: 30_000 });
    await expect(dist2.getByText('באנגו דלי'), 'название бизнеса admin нигде не показано').toHaveCount(0);
  });

  test('admin: חיפוש נתוני מפיץ שני (QA-AUTO-6aae65-P בקטלוג / -C בלקוחות) — לא נמצא; גם ב-API לפי id → ריק #3c03f6 @desktop @prod-safe', async ({ asUser }) => {
    const admin = await asUser('admin');
    await admin.goto('/catalog');
    const search = admin.getByRole('textbox', { name: /חיפוש מוצר/ });
    await expect(search).toBeVisible({ timeout: 30_000 });
    await search.fill('QA-AUTO-6aae65');
    await expect(admin.getByText('לא נמצאו מוצרים התואמים לסינון')).toBeVisible({ timeout: 15_000 });

    await admin.goto('/customers');
    const csearch = admin.getByRole('textbox', { name: /חיפוש לקוח/ });
    await expect(csearch).toBeVisible({ timeout: 30_000 });
    await csearch.fill('QA-AUTO-6aae65');
    await expect(admin.getByText('לא נמצאו לקוחות התואמים לחיפוש')).toBeVisible({ timeout: 15_000 });

    // архивные записи dist2 в UI не показываются ни у кого — проверка на уровне данных: admin не получает их по id
    await openApp(admin);
    const p = await sb(admin, 'GET', `products?select=id&id=eq.${DIST2_PRODUCT}`);
    const c = await sb(admin, 'GET', `customers?select=id&id=eq.${DIST2_CUSTOMER}`);
    expect(p.status).toBe(200);
    expect(p.body, 'товар dist2 не виден admin').toEqual([]);
    expect(c.status).toBe(200);
    expect(c.body, 'клиент dist2 не виден admin').toEqual([]);
  });

  test('API dist2: INSERT ב-customer_invites עם customer_id של לקוח «test» של admin → 403 / 42501 / FOREIGN_REFERENCE, ההזמנה לא נוצרה #3c03f6 @desktop @prod-safe', async ({ asUser }) => {
    const admin = await asUser('admin');
    await openApp(admin);
    const cust = await sb(admin, 'GET', 'customers?select=id&name=eq.test&limit=1');
    expect(cust.status).toBe(200);
    expect(cust.body.length, 'клиент «test» admin найден').toBe(1);
    const foreign = cust.body[0].id as string;
    const adminInvites = await sb(admin, 'GET', `customer_invites?select=id&customer_id=eq.${foreign}`);
    expect(adminInvites.status).toBe(200);

    const dist2 = await asUser('dist2');
    await openApp(dist2);
    const own = await sb(dist2, 'GET', `customers?select=distributor_id&id=eq.${DIST2_CUSTOMER}`);
    expect(own.status).toBe(200);
    const distributorId = own.body[0]?.distributor_id as string;
    expect(distributorId, 'свой distributor_id dist2').toBeTruthy();
    const before = await sb(dist2, 'GET', 'customer_invites?select=id');

    const r = await sb(dist2, 'POST', 'customer_invites', {
      distributor_id: distributorId, customer_id: foreign, token: crypto.randomUUID(), expires_at: new Date(Date.now() + 864e5).toISOString(),
    }, 'return=representation');
    expect(r.status, 'HTTP').toBe(403);
    expect(r.body?.code, 'код ошибки').toBe('42501');
    expect(String(r.body?.message), 'сообщение').toContain('FOREIGN_REFERENCE');

    const after = await sb(dist2, 'GET', 'customer_invites?select=id');
    expect(after.body.length, 'у dist2 приглашений не прибавилось').toBe(before.body.length);
    const adminAfter = await sb(admin, 'GET', `customer_invites?select=id&customer_id=eq.${foreign}`);
    expect(adminAfter.body.length, 'у клиента «test» admin приглашений не прибавилось').toBe(adminInvites.body.length);
  });

  test('API dist2: PATCH של הזמנה שלי ל-customer_id של לקוח admin → 403 / FOREIGN_REFERENCE, ה-customer_id לא השתנה; ההזמנה נמחקת בסוף #3c03f6 @desktop @data', async ({ asUser }) => {
    const admin = await asUser('admin');
    await openApp(admin);
    const cust = await sb(admin, 'GET', 'customers?select=id&name=eq.test&limit=1');
    expect(cust.body.length).toBe(1);
    const foreign = cust.body[0].id as string;

    const dist2 = await asUser('dist2');
    await openApp(dist2);
    const own = await sb(dist2, 'GET', `customers?select=distributor_id&id=eq.${DIST2_CUSTOMER}`);
    const distributorId = own.body[0]?.distributor_id as string;
    expect(distributorId).toBeTruthy();

    // своё приглашение на своего (архивного) клиента — удаляемое; чистка в finally
    const ins = await sb(dist2, 'POST', 'customer_invites', {
      distributor_id: distributorId, customer_id: DIST2_CUSTOMER, token: crypto.randomUUID(), expires_at: new Date(Date.now() + 864e5).toISOString(),
    }, 'return=representation');
    expect(ins.status, 'своё приглашение на своего клиента создаётся').toBe(201);
    const id = ins.body[0].id as string;
    try {
      const r = await sb(dist2, 'PATCH', `customer_invites?id=eq.${id}`, { customer_id: foreign }, 'return=representation');
      expect(r.status, 'HTTP').toBe(403);
      expect(r.body?.code, 'код ошибки').toBe('42501');
      expect(String(r.body?.message), 'сообщение').toContain('FOREIGN_REFERENCE');
      const row = await sb(dist2, 'GET', `customer_invites?select=customer_id&id=eq.${id}`);
      expect(row.body[0]?.customer_id, 'customer_id остался своим').toBe(DIST2_CUSTOMER);
    } finally {
      const del = await sb(dist2, 'DELETE', `customer_invites?id=eq.${id}`, undefined, 'return=representation');
      expect(del.status, 'приглашение удалено').toBeLessThan(300);
      const left = await sb(dist2, 'GET', `customer_invites?select=id&id=eq.${id}`);
      expect(left.body, 'приглашения не осталось').toEqual([]);
    }
  });
});
